const GR=2,GC=2;
const D={up:[1,0],down:[-1,0],left:[0,-1],right:[0,1]};
const dist=s=>Math.abs(GR-s.r)+Math.abs(GC-s.c);
export function initialState(){return {r:0,c:0,moves:0,hint:false,won:false,msg:'Move the token to the goal square.'};}
export function reduce({state,event}){
 if(event.type!=='action')return state;
 const s={...state},a=event.action;
 if(s.won){s.msg='Goal reached in '+s.moves+' moves (shortest is 4). Press Reset to play again.';return s;}
 if(a==='hint'){s.hint=true;s.msg=s.c<GC?'Hint: move Right.':'Hint: move Up.';return s;}
 const d=D[a];if(!d)return state;
 const nr=s.r+d[0],nc=s.c+d[1];
 if(nr<0||nr>2||nc<0||nc>2){s.msg='That move would leave the board.';return s;}
 s.r=nr;s.c=nc;s.moves++;s.hint=false;
 if(dist(s)===0){s.won=true;s.msg='You reached the goal in '+s.moves+' moves. The shortest route is 4 moves.';}
 else s.msg='Moved '+a+'. '+dist(s)+' steps to go.';
 return s;}
export function evaluate({state}){
 const s=state||initialState();
 const x=(s.c-1)*1.1,z=(1-s.r)*1.1;
 const right=s.c<GC;
 const q=right?[0,0,-0.7071068,0.7071068]:[-0.7071068,0,0,0.7071068];
 return {nodes:{token:{position:[x,0.35,z]},hintA:{position:[x,0.35,z],quaternion:q,visible:s.hint&&!s.won}},
 readouts:{steps:dist(s),moves:s.moves},
 goal:{status:s.won?'won':'playing',message:s.msg}};}
